#include <stdio.h>

// graph[x] will store all cities connected to city x
int graph[MAX][10];     

// size[x] tells how many neighbors city x has
int size[MAX];          

// distance[x] stores how many roads needed to reach city x
// -1 means city not visited yet
int distance[MAX];      

// Queue for BFS
int queue[MAX];
int front = 0, rear = 0;

// Add a city to the queue
void push(int city) {
    queue[rear++] = city;
}

// Remove a city from the queue
int pop() {
    return queue[front++];
}

int main() {

    int n, m;
    scanf("%d %d", &n, &m);

    // Read all roads
    for(int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);

        // Add both directions because the road is bidirectional
        graph[u][size[u]++] = v;
        graph[v][size[v]++] = u;
    }

    int s, t;
    scanf("%d %d", &s, &t);

    // Initialize all distances as -1 (not visited)
    for(int i = 1; i <= n; i++) {
        distance[i] = -1;
    }

    // Start BFS from source city
    push(s);
    distance[s] = 0;

    // BFS loop
    while(front < rear) {

        int city = pop();

        // If we reached destination, print distance
        if(city == t) {
            printf("%d\n", distance[city]);
            return 0;
        }

        // Visit all neighboring cities
        for(int i = 0; i < size[city]; i++) {
            int next_city = graph[city][i];

            // If not visited
            if(distance[next_city] == -1) {
                distance[next_city] = distance[city] + 1;
                push(next_city);
            }
        }
    }

    // If destination was never reached
    printf("-1\n");
    return 0;
}

