        int t = sc.nextInt();

        // distance[x] = number of roads from s to x
        // -1 means not visited
        int[] distance = new int[n + 1];
        Arrays.fill(distance, -1);

        Queue<Integer> queue = new LinkedList<>();

        // Start BFS
        queue.add(s);
        distance[s] = 0;

        while(!queue.isEmpty()) {

            int city = queue.poll();

            // If destination found
            if(city == t) {
                System.out.println(distance[city]);
                return;
            }

            // Visit neighbors
            for(int next_city : graph.get(city)) {
                if(distance[next_city] == -1) {
                    distance[next_city] = distance[city] + 1;
                    queue.add(next_city);
                }
            }
