#include <stdlib.h>

// Definition of linked list node
struct ListNode {
    int val;
    struct ListNode* next;
};

// Function to merge two sorted linked lists
struct ListNode* mergeLists(struct ListNode* l1, struct ListNode* l2) {

    // If first list is empty, return second list
    if (l1 == NULL)
        return l2;

    // If second list is empty, return first list
    if (l2 == NULL)
        return l1;

    // If value of l1 is smaller or equal
    if (l1->val <= l2->val) {
        // Connect l1 to the merged rest
        l1->next = mergeLists(l1->next, l2);
        return l1;
    }
    else {
        // Connect l2 to the merged rest
        l2->next = mergeLists(l1, l2->next);
        return l2;
    }
}

