        return l1;

    // If l1 value is smaller or equal
    if (l1->val <= l2->val) {
        // Recursively merge remaining nodes
        l1->next = mergeLists(l1->next, l2);
        return l1;
    }
    else {
        // Pick node from second list
        l2->next = mergeLists(l1, l2->next);
        return l2;
    }
}

