    # head moves when:
    # 1) deleting from left
    # 2) deleting from right AND n is even
    if isLeft or n % 2 == 0:
        increment = step
    else:
        increment = 0

    # Recursive call with updated values
    return solve(
        n - n // 2,       # half elements removed
        head + increment,# new head
        step * 2,         # gap doubles
        not isLeft        # direction flips
    )


def lastInteger(n):
