class Solution {
    long solve(long n, long head, long step, boolean isLeft) {
        if (n == 1) {
            return head;
        }
        long increment = (isLeft || n % 2 != 0) ? 0 : step;
        return solve(n - n / 2, head + increment, step * 2, !isLeft);
    }

    public long lastInteger(long n) {
        return solve(n, 1, 1, true);
    }
}

